from pathlib import Path


def once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        return text
    if old not in text:
        raise SystemExit(f"missing anchor: {label}")
    return text.replace(old, new, 1)


def patch_engine():
    p = Path('app/src/main/java/com/fabdata/app/ThermalEngine.kt')
    t = p.read_text()
    t = once(
        t,
        '    private val trainingPolicyStore = ThermalTrainingPolicyStore(db)\n',
        '    private val trainingPolicyStore = ThermalTrainingPolicyStore(db)\n    private val scopedTrainingPolicyStore = ThermalTrainingScopedPolicyStore(db)\n',
        'engine scoped store'
    )
    old = '''        val legacyTrainingExclusions = ThermalTrainingMaskStore(db).query(\n            sensor.id, measured.first().timestamp, measured.last().timestamp\n        )\n        val inertiaPolicy = trainingPolicyStore.ranges(ThermalTrainingTarget.INERTIA)\n        val newPolicyActive = inertiaPolicy.isNotEmpty()\n        fun trainingTimestampAccepted(timestamp: Long): Boolean {\n            if (!newPolicyActive && legacyTrainingExclusions.any { it.contains(timestamp) }) return false\n            if (inertiaPolicy.any { it.mode == ThermalTrainingRangeMode.EXCLUDE && it.contains(timestamp) }) return false\n            val exclusive = inertiaPolicy.filter { it.mode == ThermalTrainingRangeMode.EXCLUSIVE && it.enabled }\n            return exclusive.isEmpty() || exclusive.any { it.contains(timestamp) }\n        }\n\n        val acceptedMeasured = measured.filter { trainingTimestampAccepted(it.timestamp) }\n'''
    new = '''        val legacyTrainingExclusions = ThermalTrainingMaskStore(db).query(\n            sensor.id, measured.first().timestamp, measured.last().timestamp\n        )\n        val scopedSubject = ThermalTrainingSubject.inertia(sensor.id)\n        val scopedPolicyActive = scopedTrainingPolicyStore.hasAny(ThermalTrainingTarget.INERTIA, scopedSubject)\n        val inertiaPolicy = trainingPolicyStore.ranges(ThermalTrainingTarget.INERTIA)\n        val globalPolicyActive = inertiaPolicy.isNotEmpty()\n        fun trainingTimestampAccepted(timestamp: Long): Boolean {\n            if (scopedPolicyActive) {\n                return scopedTrainingPolicyStore.accepts(\n                    ThermalTrainingTarget.INERTIA, scopedSubject, timestamp\n                )\n            }\n            if (!globalPolicyActive && legacyTrainingExclusions.any { it.contains(timestamp) }) return false\n            if (inertiaPolicy.any { it.mode == ThermalTrainingRangeMode.EXCLUDE && it.contains(timestamp) }) return false\n            val exclusive = inertiaPolicy.filter { it.mode == ThermalTrainingRangeMode.EXCLUSIVE && it.enabled }\n            return exclusive.isEmpty() || exclusive.any { it.contains(timestamp) }\n        }\n\n        val acceptedMeasured = measured.filter { trainingTimestampAccepted(it.timestamp) }\n'''
    t = once(t, old, new, 'engine scoped acceptance')
    p.write_text(t)


def patch_inertia():
    p = Path('app/src/main/java/com/fabdata/app/ThermalInertiaExperiment.kt')
    t = p.read_text()
    t = once(
        t,
        '    private val trainingPolicyStore = ThermalTrainingPolicyStore(db)\n',
        '    private val trainingPolicyStore = ThermalTrainingPolicyStore(db)\n    private val scopedTrainingPolicyStore = ThermalTrainingScopedPolicyStore(db)\n',
        'inertia scoped store'
    )
    old = '''        val exclusions = ThermalTrainingMaskStore(db).query(model.sensorId, from, to) +\n            trainingPolicyStore.asExclusions(ThermalTrainingTarget.INERTIA, from, to, model.sensorId)\n'''
    new = '''        val scopedSubject = ThermalTrainingSubject.inertia(model.sensorId)\n        val policyExclusions = if (scopedTrainingPolicyStore.hasAny(ThermalTrainingTarget.INERTIA, scopedSubject)) {\n            scopedTrainingPolicyStore.asExclusions(\n                ThermalTrainingTarget.INERTIA, scopedSubject, from, to, model.sensorId\n            )\n        } else {\n            trainingPolicyStore.asExclusions(ThermalTrainingTarget.INERTIA, from, to, model.sensorId)\n        }\n        val exclusions = ThermalTrainingMaskStore(db).query(model.sensorId, from, to) + policyExclusions\n'''
    t = once(t, old, new, 'project scoped exclusions')
    old = '''        val trainingMaskSignature = trainingMaskStore.signature(sensorId)\n        val trainingPolicySignature = trainingPolicyStore.signature(ThermalTrainingTarget.INERTIA)\n        val key = "$measuredRevision|${reference.key}|$weatherSignature|${sensorId ?: -1L}|$includeHistory|$trainingMaskSignature|$trainingPolicySignature"\n'''
    new = '''        val trainingMaskSignature = trainingMaskStore.signature(sensorId)\n        val requestedScopedSubject = sensorId?.let(ThermalTrainingSubject::inertia)\n        val trainingPolicySignature = if (requestedScopedSubject != null &&\n            scopedTrainingPolicyStore.hasAny(ThermalTrainingTarget.INERTIA, requestedScopedSubject)\n        ) {\n            scopedTrainingPolicyStore.signature(ThermalTrainingTarget.INERTIA, requestedScopedSubject)\n        } else {\n            trainingPolicyStore.signature(ThermalTrainingTarget.INERTIA)\n        }\n        val key = "$measuredRevision|${reference.key}|$weatherSignature|${sensorId ?: -1L}|$includeHistory|$trainingMaskSignature|$trainingPolicySignature"\n'''
    t = once(t, old, new, 'inertia scoped signature')
    old = '''        val manualExclusions = trainingMaskStore.query(sensor.id, from, to) +\n            trainingPolicyStore.asExclusions(ThermalTrainingTarget.INERTIA, from, to, sensor.id)\n'''
    new = '''        val selectedScopedSubject = ThermalTrainingSubject.inertia(sensor.id)\n        val selectedPolicyExclusions = if (scopedTrainingPolicyStore.hasAny(\n                ThermalTrainingTarget.INERTIA, selectedScopedSubject\n            )\n        ) {\n            scopedTrainingPolicyStore.asExclusions(\n                ThermalTrainingTarget.INERTIA, selectedScopedSubject, from, to, sensor.id\n            )\n        } else {\n            trainingPolicyStore.asExclusions(ThermalTrainingTarget.INERTIA, from, to, sensor.id)\n        }\n        val manualExclusions = trainingMaskStore.query(sensor.id, from, to) + selectedPolicyExclusions\n'''
    t = once(t, old, new, 'estimate scoped exclusions')
    p.write_text(t)


def patch_wall_service():
    p = Path('app/src/main/java/com/fabdata/app/ThermalWallSolarService.kt')
    t = p.read_text()
    t = once(
        t,
        '    private val trainingPolicyStore = ThermalTrainingPolicyStore(db)\n',
        '    private val trainingPolicyStore = ThermalTrainingPolicyStore(db)\n    private val scopedTrainingPolicyStore = ThermalTrainingScopedPolicyStore(db)\n',
        'wall scoped store'
    )
    old = '''    fun train(reference: WeatherReference, wallId: String): WallSolarModel {\n        val wall = configStore.wallById(wallId) ?: error("Pan de mur introuvable")\n        val sensor = linkedRealSensors(wallId)\n            .maxByOrNull { measuredPoints(it.id).size }\n            ?: error("Aucune sonde extérieure réelle associée à ${wall.name}")\n        val measured = measuredPoints(sensor.id)\n            .filter { trainingPolicyStore.accepts(ThermalTrainingTarget.SOLAR, it.timestamp) }\n'''
    new = '''    fun train(reference: WeatherReference, wallId: String, sensorId: Long? = null): WallSolarModel {\n        val wall = configStore.wallById(wallId) ?: error("Pan de mur introuvable")\n        val linked = linkedRealSensors(wallId)\n        val sensor = sensorId?.let { wanted -> linked.firstOrNull { it.id == wanted }\n            ?: error("La sonde choisie n'est pas associée à ${wall.name}") }\n            ?: linked.maxByOrNull { measuredPoints(it.id).size }\n            ?: error("Aucune sonde extérieure réelle associée à ${wall.name}")\n        val scopedSubject = ThermalTrainingSubject.solar(wallId)\n        val scopedActive = scopedTrainingPolicyStore.hasAny(ThermalTrainingTarget.SOLAR, scopedSubject)\n        val measured = measuredPoints(sensor.id)\n            .filter { point ->\n                if (scopedActive) scopedTrainingPolicyStore.accepts(\n                    ThermalTrainingTarget.SOLAR, scopedSubject, point.timestamp\n                ) else trainingPolicyStore.accepts(ThermalTrainingTarget.SOLAR, point.timestamp)\n            }\n'''
    t = once(t, old, new, 'wall explicit sensor and scoped policy')
    p.write_text(t)


